#include <nss.h>

enum nss_status {
    NSS_STATUS_SUCCESS = 0,
    NSS_STATUS_NOTFOUND,
    NSS_STATUS_UNAVAIL
};

enum nss_status get_user_info(const char* name, struct passwd* pwd, char* buffer, size_t buflen, int* errnop) {
    const char* prefix = "vu-";
    if (strncmp(name, prefix, strlen(prefix)) != 0) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    const char* rest = name + strlen(prefix);
    char machine[256];
    char* uid_str = NULL;
    char* saveptr = NULL;

    // Extract machine name and uid string
    char* token = strtok_r((char*)rest, "-", &saveptr);
    if (!token || strlen(token) >= sizeof(machine)) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }
    strncpy(machine, token, sizeof(machine));
    machine[sizeof(machine) - 1] = '\0';

    uid_str = strtok_r(NULL, "-", &saveptr);
    if (!uid_str) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    // Convert uid to integer
    uid_t uid;
    char* endptr;
    errno = 0;
    uid = (uid_t)strtoul(uid_str, &endptr, 10);
    if (errno != 0 || *endptr != '\0') {
        *errnop = errno;
        return NSS_STATUS_UNAVAIL;
    }

    // Prepare buffer and populate the password structure
    if (buflen < strlen(name) + 1) {
        *errnop = ERANGE;
        return NSS_STATUS_UNAVAIL;
    }

    strncpy(buffer, name, buflen);
    buffer[buflen - 1] = '\0';

    pwd->pw_name = buffer;
    pwd->pw_uid = uid;
    pwd->pw_gid = uid % 1000; // Example default gid
    pwd->pw_gecos = "";
    pwd->pw_dir = "/home/virtual";
    pwd->pw_shell = "/bin/sh";

    *errnop = 0;
    return NSS_STATUS_SUCCESS;
}

