    const char *machine_start = name + 3;
    const char *uid_start = strchr(machine_start, '-');
    if (uid_start == NULL) {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    size_t machine_len = (size_t)(uid_start - machine_start);
    if (machine_len == 0) {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    if (machine_len + 1 + 1 + sizeof(uid_t) > buflen) {
        *errnop = ERANGE;
        return NSS_STATUS_UNAVAIL;
    }

    char *machine_name = buffer;
    char *uid_str = buffer + machine_len + 1;
    char *username = uid_str + strlen(uid_str) + 1;

    strncpy(machine_name, machine_start, machine_len);
    machine_name[machine_len] = '\0';

    long uid_value = strtol(uid_str, NULL, 10);
    if (uid_value <= 0 || uid_value > UINT_MAX) {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    uid_t uid = (uid_t)uid_value;

    snprintf(username, buflen - (username - buffer), "vu-%s-%lu", machine_name, uid_value);

    pwd->pw_name = username;
    pwd->pw_uid = uid;
    pwd->pw_gid = 0;
    pwd->pw_gecos = "";
    pwd->pw_dir = "/nonexistent";
    pwd->pw_shell = "/usr/sbin/nologin";

    return NSS_STATUS_SUCCESS;
